static void packet_unregister_mclist(struct net_device *dev, struct net *net)
{
	struct sock *sk;
	struct packet_sock *po;
	struct packet_mclist *ml;

	rcu_read_lock();
restart:
	sk_for_each_rcu(sk, &net->packet.sklist) {
		po = pkt_sk(sk);
		for (ml = po->mclist; ml; ml = ml->next) {
			if (ml->ifindex == dev->ifindex) {
				sock_hold(sk);
				rcu_read_unlock();
				packet_dev_mclist_delete(dev, &po->mclist);
				sock_put(sk);
				rcu_read_lock();
				goto restart;
			}
		}
	}
	rcu_read_unlock();
}

